<template><div class="mention-input"><textarea ref="input" v-bind="$attrs" :value="modelValue" :aria-expanded="choices.length>0" :aria-controls="choices.length?listId:undefined" @input="change" @keyup="search" @click="search" @keydown="keys" @blur="hide" /><ul v-if="choices.length" :id="listId" role="listbox" :aria-label="$ui('提及用户')"><li v-for="(choice,i) in choices" :key="choice.id" role="option" :aria-selected="i===selected"><button type="button" :class="{selected:i===selected}" @mousedown.prevent="choose(choice)"><strong>{{ choice.name }}</strong><small>@{{ choice.uid }}</small></button></li></ul></div></template>
<script setup lang="ts">
import {ref,onBeforeUnmount,useId} from 'vue';import{store,type PublicProfileSummary}from'@/api/store';
defineOptions({inheritAttrs:false});const props=defineProps<{modelValue:string;itemId:string}>(),emit=defineEmits<{'update:modelValue':[string]}>();const input=ref<HTMLTextAreaElement>(),choices=ref<PublicProfileSummary[]>([]),selected=ref(0),listId=useId();let timer:ReturnType<typeof setTimeout>,generation=0,tokenStart=0,tokenEnd=0;
function hide(){generation++;clearTimeout(timer);choices.value=[];}
function search(){const el=input.value;if(!el)return;const before=el.value.slice(0,el.selectionStart),match=before.match(/(?:^|[\s(])@([\p{L}\p{N}_-]{0,40})$/u);if(!match){hide();return;}tokenEnd=el.selectionStart;tokenStart=tokenEnd-match[1].length-1;clearTimeout(timer);const step=++generation;timer=setTimeout(async()=>{try{const result=await store.mentionTargets(props.itemId,match[1]);if(step===generation){choices.value=result.data;selected.value=0;}}catch{if(step===generation)choices.value=[];}},180);}
function change(event:Event){emit('update:modelValue',(event.target as HTMLTextAreaElement).value);search();}
function choose(choice:PublicProfileSummary){const el=input.value;if(!el)return;const value=el.value.slice(0,tokenStart)+'@'+choice.uid+' '+el.value.slice(tokenEnd);const position=tokenStart+choice.uid.length+2;hide();emit('update:modelValue',value);requestAnimationFrame(()=>{el.focus();el.setSelectionRange(position,position);});}
function keys(event:KeyboardEvent){if(event.key==='Escape'){hide();return;}if(!choices.value.length)return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();selected.value=(selected.value+(event.key==='ArrowDown'?1:-1)+choices.value.length)%choices.value.length;}else if(event.key==='Enter'||event.key==='Tab'){event.preventDefault();choose(choices.value[selected.value]);}}
defineExpose({focus:()=>{input.value?.focus({preventScroll:true});input.value?.scrollIntoView({block:'center',behavior:'smooth'});}});onBeforeUnmount(hide);
</script>
<style scoped>.mention-input{position:relative;min-width:0}.mention-input textarea{width:100%;display:block}.mention-input ul{position:absolute;z-index:10;left:0;right:0;max-height:240px;overflow:auto;list-style:none;margin:4px 0;padding:6px;border:1px solid var(--market-border);border-radius:10px;background:var(--market-surface);box-shadow:0 8px 24px #0002}.mention-input li button{display:flex;flex-direction:column;width:100%;align-items:flex-start;text-align:left;gap:3px;background:none;border:0;padding:10px;border-radius:6px;overflow-wrap:anywhere}.mention-input li button.selected,.mention-input li button:hover{background:var(--market-accent-soft)}.mention-input small{font-size:11px;color:var(--market-muted)}</style>
